/**
 * PURE pieces of the dedicated-server checkout (no DB, no clock, safe for client
 * bundles): the operating systems we install, billing terms, the order intent
 * parser, and the money/renewal wording. test/dedicated-order.test.ts covers it.
 *
 * Prices are always computed server-side (lib/dedicated/order.ts) from the
 * pricing rules; nothing here invents a price.
 */

export type DedicatedOs = { id: string; label: string; family: "Ubuntu" | "Debian" | "AlmaLinux" | "Rocky Linux" | "Proxmox"; note: string };

/** What our team installs by hand at handover. Linux only (no licence resale). */
export const DEDICATED_OS: DedicatedOs[] = [
  { id: "ubuntu-2404", label: "Ubuntu 24.04 LTS", family: "Ubuntu", note: "Recommended. Supported to 2029." },
  { id: "ubuntu-2204", label: "Ubuntu 22.04 LTS", family: "Ubuntu", note: "Supported to 2027." },
  { id: "debian-12", label: "Debian 12", family: "Debian", note: "Lean and stable." },
  { id: "alma-9", label: "AlmaLinux 9", family: "AlmaLinux", note: "RHEL-compatible." },
  { id: "rocky-9", label: "Rocky Linux 9", family: "Rocky Linux", note: "RHEL-compatible." },
  { id: "proxmox-9", label: "Proxmox VE 9", family: "Proxmox", note: "Run your own virtual machines." },
];

export function osById(id: string): DedicatedOs | null {
  return DEDICATED_OS.find((o) => o.id === id) ?? null;
}

/**
 * Billing terms. The pricing rules define one monthly price; a 12-month term is
 * that price x 12 paid up front (no discount exists in the rules, so none is
 * shown or applied). Renewal is stated as charged: "$X/yr", never a monthly split.
 */
export const DEDICATED_TERMS = [1, 12] as const;
export type DedicatedTerm = (typeof DEDICATED_TERMS)[number];

export function isDedicatedTerm(n: unknown): n is DedicatedTerm {
  return n === 1 || n === 12;
}

export const usd = (cents: number) =>
  `$${(Math.round(cents) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

/** The renewal as it is charged: "$189.99/mo", "$2,279.88/yr", "$549.00 every 3 months". */
export function renewalLabel(monthlyCents: number, termMonths: number): string {
  const t = Math.max(1, Math.round(termMonths || 1));
  const total = monthlyCents * t;
  if (t === 1) return `${usd(total)}/mo`;
  if (t === 12) return `${usd(total)}/yr`;
  return `${usd(total)} every ${t} months`;
}

export function termLabel(termMonths: number): string {
  return termMonths === 12 ? "Annual" : termMonths === 1 ? "Monthly" : `Every ${termMonths} months`;
}

/** Customer promise for an in-stock build. */
export const SETUP_ETA = "Online within 24 hours";

export type DedicatedOrderIntent = {
  /** Catalogue item id of the regional build (opaque id, not an upstream code). */
  itemId: string;
  /** Nxeon region code, e.g. "sgp1". */
  region: string;
  os: string;
  termMonths: DedicatedTerm;
  /** Chosen option ids per family; null = the build's default. */
  memoryId: string | null;
  storageId: string | null;
  bandwidthId: string | null;
  /** Customer label for the machine. */
  label: string;
  /** Client idempotency key: one key places at most one order. */
  orderKey: string;
};

const ID_RE = /^[a-z0-9]{8,40}$/i;
const REGION_RE = /^[a-z]{3}\d$/;
const KEY_RE = /^[A-Za-z0-9_-]{12,64}$/;

/** Strict parser for anything that crosses the client/server or Stripe-metadata boundary. */
export function parseDedicatedIntent(raw: unknown): DedicatedOrderIntent | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const optId = (v: unknown) => (v == null || v === "" ? null : typeof v === "string" && ID_RE.test(v) ? v : undefined);
  const memoryId = optId(r.memoryId);
  const storageId = optId(r.storageId);
  const bandwidthId = optId(r.bandwidthId);
  const termMonths = r.termMonths;
  if (typeof r.itemId !== "string" || !ID_RE.test(r.itemId)) return null;
  if (typeof r.region !== "string" || !REGION_RE.test(r.region)) return null;
  if (typeof r.os !== "string" || !osById(r.os)) return null;
  if (!isDedicatedTerm(termMonths)) return null;
  if (memoryId === undefined || storageId === undefined || bandwidthId === undefined) return null;
  if (typeof r.orderKey !== "string" || !KEY_RE.test(r.orderKey)) return null;
  const label = typeof r.label === "string" ? r.label.replace(/[\u0000-\u001f<>]/g, "").trim().slice(0, 40) : "";
  return { itemId: r.itemId, region: r.region, os: r.os, termMonths, memoryId, storageId, bandwidthId, label, orderKey: r.orderKey };
}

/** The money for one order. All integer USD cents. */
export type DedicatedOrderMoney = {
  monthlyCents: number;
  termMonths: DedicatedTerm;
  /** monthly x term */
  termCents: number;
  setupCents: number;
  /** term + setup, before tax */
  netCents: number;
  taxCents: number;
  taxRatePercent: number;
  taxCountry: string;
  /** what is charged today */
  totalCents: number;
};

export function orderMoney(args: { monthlyCents: number; termMonths: DedicatedTerm; setupCents: number; taxRatePercent: number; taxCountry?: string }): DedicatedOrderMoney {
  const monthlyCents = Math.max(0, Math.round(args.monthlyCents));
  const setupCents = Math.max(0, Math.round(args.setupCents));
  const termCents = monthlyCents * args.termMonths;
  const netCents = termCents + setupCents;
  const rate = Number.isFinite(args.taxRatePercent) && args.taxRatePercent > 0 ? args.taxRatePercent : 0;
  const taxCents = Math.round((netCents * rate) / 100);
  return { monthlyCents, termMonths: args.termMonths, termCents, setupCents, netCents, taxCents, taxRatePercent: rate, taxCountry: rate > 0 ? args.taxCountry ?? "" : "", totalCents: netCents + taxCents };
}

/** Parse a price stamped into Stripe metadata (null when malformed). */
export function parseStampedMoney(raw: unknown): DedicatedOrderMoney | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const int = (v: unknown) => (typeof v === "number" && Number.isInteger(v) && v >= 0 ? v : null);
  const monthly = int(r.monthlyCents), setup = int(r.setupCents), total = int(r.totalCents), tax = int(r.taxCents);
  const term = r.termMonths === 1 || r.termMonths === 12 ? r.termMonths : null;
  if (monthly == null || setup == null || total == null || tax == null || term == null) return null;
  const rate = typeof r.taxRatePercent === "number" && Number.isFinite(r.taxRatePercent) ? r.taxRatePercent : 0;
  const m = orderMoney({ monthlyCents: monthly, termMonths: term, setupCents: setup, taxRatePercent: 0 });
  // Re-derive the totals; refuse a stamp whose arithmetic doesn't add up.
  if (m.netCents + tax !== total) return null;
  return { ...m, taxCents: tax, taxRatePercent: rate, taxCountry: typeof r.taxCountry === "string" ? r.taxCountry.slice(0, 2) : "", totalCents: total };
}

/** Renewal date for a term starting at `from` (calendar months, clamped to month end). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from.getTime());
  const day = d.getUTCDate();
  d.setUTCDate(1);
  d.setUTCMonth(d.getUTCMonth() + months);
  const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  d.setUTCDate(Math.min(day, last));
  return d;
}

/** Status timeline for the customer dashboard. */
export type TimelineStep = { key: "ordered" | "building" | "online"; label: string; state: "done" | "current" | "todo"; at: string | null; note: string };

export function serverTimeline(s: { statusKey: string; orderedAt: string; provisionedAt: string | null }): TimelineStep[] {
  const k = s.statusKey;
  const online = k === "ACTIVE" || k === "SUSPENDED" || (k === "CANCELLED" && !!s.provisionedAt);
  const building = online || k === "PROVISIONING";
  return [
    { key: "ordered", label: "Order received", state: "done", at: s.orderedAt, note: "Payment confirmed. Your machine is reserved." },
    { key: "building", label: "Being built", state: building ? (online ? "done" : "current") : k === "PENDING" ? "current" : "todo", at: null, note: "Our engineers install your OS, harden it and run burn-in checks." },
    { key: "online", label: "Online", state: online ? "done" : "todo", at: s.provisionedAt, note: "IP addresses and your login appear here." },
  ];
}
  }
}

/** Reveal a rescue password our team stored (key-based rescue needs none). */
export async function revealDedicatedRescueSecret(serverId: string): Promise<{ ok: true; secret: string } | Fail> {
  try {
    const { user, server } = await owned(serverId);
    if (!checkRateLimit(`ded-rescue:${user.id}`, { max: 20, windowMs: 60 * 60_000 }).ok) return { ok: false, error: "Try again later." };
    if (!server.rescueSecretEnc) return { ok: false, error: "No rescue password is stored. Rescue mode uses your SSH key." };
    const secret = decryptSecret(server.rescueSecretEnc);
    if (!secret) return { ok: false, error: "Could not read the stored password. Please contact support." };
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: user.id, action: "rescue_secret_viewed" } });
    return { ok: true, secret };
  } catch {
    return NF;
  }
}

/* ---------------- extra IPs ---------------- */

export async function quoteDedicatedExtraIps(serverId: string, quantity: number, useWallet = true): Promise<{ ok: true; quote: IpQuote; walletApplied: number; cardCents: number; balanceCents: number } | Fail> {
  try {
    const { user, server } = await owned(serverId);
    const q = await quoteExtraIps(server.id, user.id, quantity);
    const sp = walletSplit({ dueCents: q.chargeCents, balanceCents: user.balanceCents, useWallet });
    return { ok: true, quote: q, walletApplied: sp.walletApplied, cardCents: sp.cardCents, balanceCents: user.balanceCents };
  } catch (e) {
    return e instanceof IpOrderError ? { ok: false, error: e.message } : NF;
  }
}

export async function payDedicatedExtraIps(serverId: string, quantity: number, orderKey: string, useWallet = true): Promise<{ ok: true; orderId: string } | { ok: true; checkout: CustomCheckout; cardCents: number } | Fail> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, server } = await owned(serverId);
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!isExtraIpSize(quantity)) return { ok: false, error: "Pick 1, 4 or 8 addresses." };
    if (typeof orderKey !== "string" || !/^[A-Za-z0-9_-]{12,64}$/.test(orderKey)) return { ok: false, error: "Refresh and try again." };
    if (!checkRateLimit(`ded-ip-pay:${user.id}`, { max: 10, windowMs: 10 * 60_000 }).ok) return { ok: false, error: "Too many attempts. Please wait a few minutes." };
    const open = await db.dedicatedIpOrder.count({ where: { dedicatedServerId: server.id, status: { in: ["PAID", "APPROVED", "ORDERING"] } } });
    if (open > 0) return { ok: false, error: "An extra-IP order for this server is already in progress." };
    const q = await quoteExtraIps(server.id, user.id, quantity);
    const sp = walletSplit({ dueCents: q.chargeCents, balanceCents: user.balanceCents, useWallet });
    if (sp.cardCents <= 0) {
      const { orderId } = await placeDedicatedIpOrder(user, server.id, q.quantity, orderKey);
      revalidatePath(`/dashboard/dedicated/${server.id}`);
      return { ok: true, orderId };
    }
    const checkout = await createDedicatedIpOrderPaymentSession(user, sp.cardCents, { serverId: server.id, quantity: q.quantity, orderKey, chargeCents: q.chargeCents, unitMonthlyCents: q.unitMonthlyCents }, server.label);
    if (!checkout) return { ok: false, error: "Card payments aren't available right now. Top up your wallet instead." };
    return { ok: true, checkout, cardCents: sp.cardCents };
  } catch (e) {
    return e instanceof IpOrderError ? { ok: false, error: e.message } : { ok: false, error: "Something went wrong. Nothing was charged." };
  }
}

"use server";

/**
 * CUSTOMER checkout actions for dedicated servers (/dashboard/dedicated/order/*).
 *
 * Gate: every action re-checks dedicatedAccessFor(user) (public flag OR the
 * private-preview allowlist) and answers "Not found" otherwise — the feature
 * does not exist for anyone else.
 *
 * Money path = the portal's wallet-then-card shape (lib/actions-dedicated-ip.ts,
 * payAndDeploy): server quote -> walletSplit -> either place now from the wallet,
 * or open a Stripe Custom Checkout session for the card remainder (rendered by
 * components/nx/NxCardFields) whose fulfilment places the order. The client never
 * supplies a price.
 */
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";
import { createDedicatedOrderPaymentSession, type CustomCheckout } from "./stripe";
import { dedicatedAccessFor } from "./dedicated/gate";
import { DedicatedOrderError, loadOrderBuild, orderPreviewAll, placeDedicatedOrder, quoteDedicatedOrder, toCustomerQuote, type CustomerQuote, type OrderBuild } from "./dedicated/order";
import { parseDedicatedIntent } from "./dedicated/order-core";

const NOT_FOUND = "Not found";

async function gatedUser() {
  const user = await requireUser();
  const access = await dedicatedAccessFor(user);
  if (!access.allowed) throw new Error(NOT_FOUND);
  return { user, previewAll: await orderPreviewAll(access.preview) };
}

/**
 * One build for the configurator, fetched by the client when a catalogue card is
 * opened (or hovered, as a prefetch), so catalogue -> configure -> back never
 * reloads the page. Read-only; served from the catalogue cache.
 */
export async function loadDedicatedBuildAction(id: unknown): Promise<OrderBuild | null> {
  try {
    const { previewAll } = await gatedUser();
    if (typeof id !== "string" || !/^[a-z0-9]{8,40}$/i.test(id)) return null;
    return await loadOrderBuild(id, previewAll);
  } catch {
    return null;
  }
}

export type DedicatedQuoteResult =
  | { ok: true; quote: CustomerQuote; balanceCents: number; walletApplied: number; cardCents: number }
  | { ok: false; error: string };

/** Re-price a configuration (review step). Read-only. */
export async function quoteDedicatedOrderAction(raw: unknown, useWallet = true): Promise<DedicatedQuoteResult> {
  try {
    const { user, previewAll } = await gatedUser();
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const q = await quoteDedicatedOrder(intent, user, { previewAll });
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: user.balanceCents, useWallet });
    return { ok: true, quote: toCustomerQuote(q), balanceCents: user.balanceCents, walletApplied: split.walletApplied, cardCents: split.cardCents };
  } catch (e) {
    if (e instanceof DedicatedOrderError) return { ok: false, error: e.message };
    return { ok: false, error: e instanceof Error && e.message === NOT_FOUND ? NOT_FOUND : "We couldn't price that configuration. Please try again." };
  }
}

export type DedicatedPayResult =
  | { ok: true; serverId: string }
  | { ok: true; checkout: CustomCheckout; cardCents: number; walletApplied: number }
  | { ok: false; error: string };

/**
 * Pay for a configuration. Wallet covers it -> the order is placed now.
 * Otherwise -> a card session for exactly the remainder; the order is placed when
 * the card clears (lib/fulfil-checkout.ts), never before.
 */
export async function payDedicatedOrder(raw: unknown, useWallet = true): Promise<DedicatedPayResult> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, previewAll } = await gatedUser();
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!checkRateLimit(`dedicated-pay:${user.id}`, { max: 10, windowMs: 10 * 60_000 }).ok) {
      return { ok: false, error: "Too many attempts. Please wait a few minutes and try again." };
    }
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const q = await quoteDedicatedOrder(intent, user, { previewAll });
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: user.balanceCents, useWallet });
    if (split.cardCents <= 0) {
      const { serverId } = await placeDedicatedOrder(user, intent, { previewAll, via: "wallet" });
      return { ok: true, serverId };
    }
    const checkout = await createDedicatedOrderPaymentSession(user, split.cardCents, intent, q.money, `${q.spec.name} · ${q.regionLabel}`);
    if (!checkout) return { ok: false, error: "Card payments aren't available right now. Top up your wallet to cover the order instead." };
    return { ok: true, checkout, cardCents: split.cardCents, walletApplied: split.walletApplied };
  } catch (e) {
    if (e instanceof DedicatedOrderError) return { ok: false, error: e.message };
    if (e instanceof Error && e.message === NOT_FOUND) return { ok: false, error: NOT_FOUND };
    return { ok: false, error: "Something went wrong preparing your payment. Nothing was charged. Please try again." };
  }
}
/** The card-leg analogue of `createOrderCheckout`, for the new embedded Payment
 *  step. Same pricing/refusal rules (see that function's doc comment); the only
 *  difference is `ui_mode`. */
export async function createOrderPaymentSession(
  user: CardUser,
  amountCents: number,
  intent: OrderIntent,
  sold?: OrderPrice | null,
  campaign?: string,
  promoReservationToken?: string | null,
  couponReservationToken?: string | null,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const price = sold ?? orderPriceOf(await orderQuote(intent, { userId: user.id }));
  const orderTotalCents = price.chargeCents + (price.taxCents ?? 0);
  if (orderTotalCents < amountCents) {
    throw new Error(`Order payment session: card leg ${amountCents}c exceeds the order total ${orderTotalCents}c`);
  }
  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await createCheckoutSessionLogged(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      // Custom Checkout's client-side `checkout.confirm({ savePaymentMethod })`
      // (components/customer/PaymentStep.tsx) throws `IntegrationError:
      // savePaymentMethod cannot be used unless the Checkout Session was created
      // with saved_payment_method_options[payment_method_save]=enabled` without
      // this — a real bug caught by an end-to-end staging payment attempt before
      // promoting to prod: every card payment through the embedded PaymentStep
      // failed 100% of the time with a generic "something went wrong" message.
      saved_payment_method_options: { payment_method_save: "enabled" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [
        {
          price_data: { currency: "usd", product_data: { name: `Nxeon VPS — ${intent.hostname}` }, unit_amount: amountCents },
          quantity: 1,
        },
      ],
      metadata: {
        nxeonUserId: user.id,
        nxeonOrder: packMetadata("Order intent", slim),
        nxeonOrderPrice: packMetadata("Order price", price),
        nxeonPromoCampaign: sanitizeCampaign(campaign),
        ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
        ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
      },
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    },
    EMBEDDED_REQUEST_OPTS,
  );
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

/**
 * Card leg of a dedicated-server order (lib/actions-dedicated-order.ts), for the
 * portal's inline card form (components/nx/NxCardFields — ui_mode "elements").
 * Same shape as createOrderPaymentSession: the card is charged `amountCents`
 * (the remainder after wallet credit); the intent and the FULL stamped price ride
 * in metadata so fulfilment (lib/fulfil-checkout.ts -> placeDedicatedOrder)
 * debits exactly that total back out of the wallet the card leg just funded.
 */
export async function createDedicatedOrderPaymentSession(
  user: CardUser,
  amountCents: number,
  intent: DedicatedOrderIntent,
  sold: DedicatedOrderMoney,
  lineName: string,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  if (sold.totalCents < amountCents) {
    throw new Error(`Dedicated order payment session: card leg ${amountCents}c exceeds the order total ${sold.totalCents}c`);
  }
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      saved_payment_method_options: { payment_method_save: "enabled" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [{ price_data: { currency: "usd", product_data: { name: `Nxeon Bare Metal Dedicated Server — ${lineName}`.slice(0, 120) }, unit_amount: amountCents }, quantity: 1 }],
      metadata: {
        nxeonUserId: user.id,
        nxeonDedicatedOrder: packMetadata("Dedicated order intent", intent),
        nxeonDedicatedOrderPrice: packMetadata("Dedicated order price", sold),
      },
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    },
    EMBEDDED_REQUEST_OPTS,
  );
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

/** Card leg of an extra-IP purchase for a dedicated server (same shape as the dedicated order session). */
export async function createDedicatedIpOrderPaymentSession(
  user: CardUser,
  amountCents: number,
  meta: { serverId: string; quantity: 1 | 4 | 8; orderKey: string; chargeCents: number; unitMonthlyCents: number },
  lineName: string,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  if (meta.chargeCents < amountCents) throw new Error(`Dedicated IP session: card leg ${amountCents}c exceeds the charge ${meta.chargeCents}c`);
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      saved_payment_method_options: { payment_method_save: "enabled" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [{ price_data: { currency: "usd", product_data: { name: `Nxeon extra IPs — ${lineName}`.slice(0, 120) }, unit_amount: amountCents }, quantity: 1 }],
      metadata: { nxeonUserId: user.id, nxeonDedicatedIpOrder: packMetadata("Dedicated IP order", meta) },
