/**
 * Re-price an intent from the catalogue + pricing rules. Throws DedicatedOrderError
 * with a customer-safe message when the build, region, option or stock is not orderable.
 * `requireStock` is false only at card-leg fulfilment (the card already cleared; a
 * stock change in the meantime is handled by staff, never by eating the payment).
 */
export async function quoteDedicatedOrder(
  intent: DedicatedOrderIntent,
  user: Pick<User, "billingCountry" | "vatId">,
  opts: { previewAll: boolean; requireStock?: boolean },
): Promise<InternalQuote> {
  const item = await db.dedicatedCatalogItem.findFirst({
    where: { id: intent.itemId, currency: "USD", ...(opts.requireStock === false ? {} : { removedAt: null, ...(opts.previewAll ? {} : { visible: true }) }) },
    include: { options: true },
  });
  if (!item) throw new DedicatedOrderError("This build is no longer available.");
  const os = osById(intent.os);
  if (!os) throw new DedicatedOrderError("Pick an operating system.");
  const region = regionByCode(intent.region);
  if (!region) throw new DedicatedOrderError("Pick a location.");
  const { rules, enabledRegions } = await loadRules();
  const rows = (await loadAvailability([item.planCode])).get(item.planCode) ?? [];
  const regionRow = itemRegions(item.datacenters, stockByDc(rows), enabledRegions, item.hiddenRegions).find((r) => r.code === intent.region);
  if (!regionRow || (opts.requireStock !== false && (!regionRow.offered || regionRow.hidden))) throw new DedicatedOrderError("This build isn't offered in that location.");

  const memory = pickOption(item, "memory", intent.memoryId);
  const storage = pickOption(item, "storage", intent.storageId);
  const bandwidth = pickOption(item, "bandwidth", intent.bandwidthId);
  const st = comboStock(rows, regionRow.dcs, memory, storage);
  const stock = publicStock(st.code);
  if (opts.requireStock !== false && !orderableStock(st.code)) {
    throw new DedicatedOrderError(`That configuration isn't in stock in ${region.customerLabel} right now. Try another memory or storage choice, or another location.`);
  }
  const price = sellFor(item, rules, memory, storage, bandwidth);
  const tax = await taxContextForUser(user);
  const money = orderMoney({ monthlyCents: price.sellMonthly, termMonths: intent.termMonths, setupCents: price.sellSetup, taxRatePercent: tax.ratePercent, taxCountry: tax.country });
  const fallbackDc = regionRow.dcs[0] ?? null;
  return {
    item,
    memory,
    storage,
    bandwidth,
    datacenter: st.dc ?? fallbackDc,
    costMonthlyCents: price.costMonthly,
    stock,
    spec: {
      name: brandSafe(item.displayName) || nxNames(await catalogSnapshot()).get(hardwareKey(item)) || nxName(nxInput(item)),
      family: nxFamily(nxInput(item)),
      cpu: cpuText(item),
      cores: item.cpuCores * Math.max(1, item.cpuCount),
      threads: item.cpuThreads * Math.max(1, item.cpuCount),
      ramGb: memory?.ramGb ?? item.defaultRamGb ?? 0,
      storage: storage ? optLabel(storage) : brandSafe(item.defaultStorage),
      bandwidth: bandwidth ? optLabel(bandwidth) : item.defaultBandwidthMbps ? `${bwText(item.defaultBandwidthMbps)} public bandwidth` : "",
      gpu: defaultOf(item, "gpu") ? brandSafe(defaultOf(item, "gpu")!.label) : null,
    },
    regionLabel: region.customerLabel,
    osLabel: os.label,
    money,
  };
}

/* ---------------- place ---------------- */

/** Claim an order key exactly once (FulfilledSession's UNIQUE id is the lock). */
async function claimOrderKey(userId: string, orderKey: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: `dedorder:${userId}:${orderKey}`, kind: "dedicatedOrder" } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false;
    throw e;
  }
}

/**
 * Debit the wallet for the order total, write the PAID invoice and the PENDING
 * DedicatedServer row — one transaction. `sold` is the price stamped before a card
 * leg cleared (fulfilment path); omitted on the wallet-only path, where the price
 * is the fresh quote taken in the same request. Idempotent on intent.orderKey:
 * a repeat returns the server created the first time.
 */
export async function placeDedicatedOrder(
  user: User,
  intent: DedicatedOrderIntent,
  opts: { previewAll: boolean; sold?: DedicatedOrderMoney | null; via: "wallet" | "card" },
): Promise<{ serverId: string; created: boolean }> {
  const existing = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
  if (existing) return { serverId: existing.id, created: false };

  const q = await quoteDedicatedOrder(intent, user, { previewAll: opts.previewAll, requireStock: opts.via === "wallet" });
  const money = opts.sold ?? q.money;
  if (!(await claimOrderKey(user.id, intent.orderKey))) {
    const again = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
    if (again) return { serverId: again.id, created: false };
    throw new DedicatedOrderError("This order is already being placed. Refresh in a moment.");
  }

  const now = new Date();
  const renewalDate = addMonths(now, money.termMonths);
  const nxLabel = q.spec.name;
  const label = intent.label || `${nxLabel} · ${q.regionLabel}`;
  const desc = `Bare Metal Dedicated Server — ${label}`;
  const lines = [
    {
      description:
        `${nxLabel}: ${q.spec.cpu}, ${q.spec.ramGb} GB RAM, ${q.spec.storage}${q.spec.bandwidth ? `, ${q.spec.bandwidth}` : ""} · ${q.regionLabel} · ${q.osLabel}\n` +
        `${termLabel(money.termMonths)} term · renews ${renewalLabel(money.monthlyCents, money.termMonths)} on ${renewalDate.toISOString().slice(0, 10)}`,
      qty: 1,
      unitCents: money.termCents,
      amountCents: money.termCents,
    },
    ...(money.setupCents > 0 ? [{ description: "One-time setup", qty: 1, unitCents: money.setupCents, amountCents: money.setupCents }] : []),
  ];
  const orderConfig = {
    via: opts.via,
    catalogItemId: q.item.id,
    planCode: q.item.planCode, // ADMIN-ONLY (orderConfig never reaches a customer view)
    memory: q.memory ? { id: q.memory.id, label: q.memory.label, productCode: q.memory.productCode } : null,
    storage: q.storage ? { id: q.storage.id, label: q.storage.label, productCode: q.storage.productCode } : null,
    bandwidth: q.bandwidth ? { id: q.bandwidth.id, label: q.bandwidth.label, productCode: q.bandwidth.productCode } : null,
    os: intent.os,
    osLabel: q.osLabel,
    region: intent.region,
    datacenter: q.datacenter,
    stockAtOrder: q.stock,
    money,
  };

  try {
    const serverId = await db.$transaction(async (tx) => {
      await assertSpendCap(user, money.totalCents, tx);
      await debitWallet(tx, user.id, money.totalCents);
      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -money.totalCents, description: desc.slice(0, 190) } });
      const inv = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: desc.slice(0, 190),
          status: "PAID",
          lineItems: lines,
          taxCents: money.taxCents,
          taxRatePercent: money.taxRatePercent,
          taxCountry: money.taxCountry || null,
          period: { start: now, end: renewalDate },
        }),
        select: { id: true },
      });
      const s = await tx.dedicatedServer.create({
        data: {
          userId: user.id,
          label,
          catalogItemId: q.item.id,
          cpu: q.spec.cpu,
          cores: q.spec.cores,
          threads: q.spec.threads,
          ramGb: q.spec.ramGb,
          storage: q.spec.storage,
          bandwidth: q.spec.bandwidth,
          region: intent.region,
          datacenter: q.datacenter,
          costMonthlyCents: q.costMonthlyCents,
          os: q.osLabel,
          status: "PENDING",
          renewalDate,
          renewalMonthlyCents: money.monthlyCents,
          termMonths: money.termMonths,
          setupFeeCents: money.setupCents,
          invoiceIds: [inv.id],
          orderKey: intent.orderKey,
          orderConfig: orderConfig as object,
          notes: `Ordered online (${opts.via}). Build: ${q.item.planCode} in ${q.datacenter ?? "?"}; memory ${q.memory?.label ?? "default"}; storage ${q.storage?.label ?? "default"}; bandwidth ${q.bandwidth?.label ?? "default"}; OS ${q.osLabel}. Stock at order: ${q.stock}.`,
        },
        select: { id: true },
      });
      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: user.id, action: "ordered", detail: `paid ${money.totalCents}c via ${opts.via}; invoice ${inv.id}` } });
      await tx.auditLog.create({ data: { userId: user.id, action: "dedicated.order", detail: `${s.id} item=${q.item.id} region=${intent.region} total=${money.totalCents} via=${opts.via}` } });
      return s.id;
    });

    // Best-effort notices (never undo a placed, paid order).
    try {
      await db.notification.create({
        data: { userId: user.id, title: "Bare metal server ordered", body: `We're building ${label}. It will be online within 24 hours; we'll post its IP and login on the server page.`, href: `/dashboard/dedicated/${serverId}` },
      });
      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
      if (admins.length) {
        await db.notification.createMany({
          data: admins.map((a) => ({ userId: a.id, title: `New bare metal order: ${label}`, body: `${user.email} paid ${renewalLabel(money.monthlyCents, money.termMonths)} (${q.regionLabel}). Build it by hand.`, href: `/admin/dedicated/servers/${serverId}` })),
        });
      }
    } catch {
      /* notices are best-effort */
    }
    return { serverId, created: true };
  } catch (e) {
    // Release the claim so a retry (after a top-up) can place the order.
    await db.fulfilledSession.delete({ where: { stripeSessionId: `dedorder:${user.id}:${intent.orderKey}` } }).catch(() => {});
    if (e instanceof InsufficientBalanceError) throw new DedicatedOrderError("Insufficient balance. Top up your wallet or pay the rest by card.");
    if (e instanceof SpendCapError) throw new DedicatedOrderError(e.message);
    throw e;
  }
}


/** The NX name of the build a machine was ordered from (null when unknown / withdrawn). */
export async function planNameForItem(itemId: string | null | undefined): Promise<string | null> {
  if (!itemId) return null;
  const snap = await catalogSnapshot();
  const it = snap.items.find((i) => i.id === itemId);
  if (!it) return null;
  return brandSafe(it.displayName) || nxNames(snap).get(hardwareKey(it)) || null;
}

export type IpQuote = { quantity: ExtraIpSize; unitMonthlyCents: number; monthlyCents: number; chargeCents: number; renewalAfter: string };

export async function quoteExtraIps(serverId: string, userId: string, quantity: unknown, now = new Date()): Promise<IpQuote> {
  if (!isExtraIpSize(quantity)) throw new IpOrderError("Pick 1, 4 or 8 addresses.");
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || s.userId !== userId) throw new IpOrderError("Not found");
  if (s.status !== "ACTIVE") throw new IpOrderError("Extra IPs can be added once the server is online.");
  const unit = await dedicatedIpMonthlyCents();
  const chargeCents = extraIpProrateCents({ unitMonthlyCents: unit, quantity, renewalDate: s.renewalDate, termMonths: s.termMonths, now });
  const nextMonthly = (s.renewalMonthlyCents ?? 0) + unit * quantity;
  return { quantity, unitMonthlyCents: unit, monthlyCents: unit * quantity, chargeCents, renewalAfter: renewalLabel(nextMonthly, s.termMonths) };
}

async function claim(key: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: key, kind: "dedicatedIpOrder" } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false;
    throw e;
  }
}

/** Debit + invoice + PAID order row (one transaction). Idempotent on orderKey. */
export async function placeDedicatedIpOrder(user: User, serverId: string, quantity: ExtraIpSize, orderKey: string, sold?: { chargeCents: number; unitMonthlyCents: number } | null): Promise<{ orderId: string; created: boolean }> {
  const existing = await db.dedicatedIpOrder.findFirst({ where: { userId: user.id, orderKey }, select: { id: true } });
  if (existing) return { orderId: existing.id, created: false };
  const q = sold ? null : await quoteExtraIps(serverId, user.id, quantity);
  const chargeCents = sold?.chargeCents ?? q!.chargeCents;
  const unit = sold?.unitMonthlyCents ?? q!.unitMonthlyCents;
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || s.userId !== user.id) throw new IpOrderError("Not found");
  const key = `dedip:${user.id}:${orderKey}`;
  if (!(await claim(key))) {
    const again = await db.dedicatedIpOrder.findFirst({ where: { userId: user.id, orderKey }, select: { id: true } });
    if (again) return { orderId: again.id, created: false };
    throw new IpOrderError("This order is already being placed.");
  }
  const what = quantity === 1 ? "1 extra IPv4 address" : `${quantity} extra IPv4 addresses (/${prefixForSize(quantity)})`;
  try {
    const orderId = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -chargeCents, description: `Extra IPs (bare metal) — ${s.label}`.slice(0, 190) } });
      const inv = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: `Bare Metal Dedicated Server extra IPs — ${s.label}`.slice(0, 190),
          status: "PAID",
          lineItems: [{ description: `${what} for ${s.label}, prorated to the next renewal. Then ${renewalLabel(unit * quantity, s.termMonths)} added to the renewal.`, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
        }),
        select: { id: true },
      });
      const o = await tx.dedicatedIpOrder.create({ data: { dedicatedServerId: s.id, userId: user.id, quantity, unitMonthlyCents: unit, chargedCents: chargeCents, invoiceId: inv.id, orderKey }, select: { id: true } });
      await tx.dedicatedServer.update({ where: { id: s.id }, data: { invoiceIds: { push: inv.id } } });
      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: user.id, action: "ip_order_paid", detail: `${o.id} qty=${quantity} charged=${chargeCents}` } });
      await tx.auditLog.create({ data: { userId: user.id, action: "dedicated.ip_order", detail: `${o.id} server=${s.id} qty=${quantity} charged=${chargeCents}` } });
      return o.id;
    });
    try {
      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
      if (admins.length) await db.notification.createMany({ data: admins.map((a) => ({ userId: a.id, title: `Approve extra IPs: ${s.label}`, body: `${user.email} paid for ${what}. Approve to order them.`, href: `/admin/dedicated/servers/${s.id}` })) });
    } catch {
      /* best-effort */
    }
    return { orderId, created: true };
  } catch (e) {
    await db.fulfilledSession.delete({ where: { stripeSessionId: key } }).catch(() => {});
    if (e instanceof InsufficientBalanceError) throw new IpOrderError("Insufficient balance. Top up your wallet or pay the rest by card.");
    throw e;
  }
}

/** ADMIN: approve -> enqueue the upstream order job. */
export async function approveIpOrder(orderId: string, adminId: string): Promise<string> {
  const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, include: { server: true } });
  if (!o) throw new IpOrderError("Not found");
  if (o.status !== "PAID") throw new IpOrderError(`This order is ${o.status.toLowerCase()}, not awaiting approval.`);
  const country = regionByCode(o.server.region)?.country ?? "";
  const job = await db.$transaction(async (tx) => {
    const flipped = await tx.dedicatedIpOrder.updateMany({ where: { id: o.id, status: "PAID" }, data: { status: "APPROVED", approvedById: adminId, approvedAt: new Date() } });
    if (flipped.count !== 1) throw new IpOrderError("Already handled.");
