/** ADMIN: reject -> full refund to the customer's wallet. */
export async function rejectIpOrder(orderId: string, adminId: string, reason: string): Promise<void> {
  const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, include: { server: { select: { label: true } } } });
  if (!o) throw new IpOrderError("Not found");
  if (o.status !== "PAID" && o.status !== "FAILED") throw new IpOrderError(`This order is ${o.status.toLowerCase()}; it can't be rejected now.`);
  await db.$transaction(async (tx) => {
    const flipped = await tx.dedicatedIpOrder.updateMany({ where: { id: o.id, status: o.status }, data: { status: "REJECTED", rejectReason: reason.slice(0, 300) || null, approvedById: adminId } });
    if (flipped.count !== 1) throw new IpOrderError("Already handled.");
    if (o.chargedCents > 0) {
      await tx.user.update({ where: { id: o.userId }, data: { balanceCents: { increment: o.chargedCents } } });
      await tx.walletTransaction.create({ data: { userId: o.userId, amountCents: o.chargedCents, description: `Refund: extra IPs — ${o.server.label}`.slice(0, 190) } });
    }
    await tx.auditLog.create({ data: { userId: adminId, action: "dedicated.ip_order.reject", detail: `${o.id} refunded=${o.chargedCents} ${reason.slice(0, 200)}` } });
  });
  await db.notification.create({ data: { userId: o.userId, title: "Extra IP order refunded", body: `We couldn't add those addresses to ${o.server.label}${reason ? `: ${reason}` : ""}. The full amount is back in your wallet.`, href: `/dashboard/dedicated/${o.dedicatedServerId}` } }).catch(() => {});
}

