  // credit, which equals the order's card leg) so ad/analytics revenue is never a foreign
  // number labelled as dollars.
  const localUsd = session.metadata?.nxeonLocalPay ? walletCreditCents(session) : 0;
  const value = localUsd > 0 ? localUsd / 100 : typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
  const currency = localUsd > 0 ? "USD" : (session.currency ?? "usd").toUpperCase();
