/** URGENT in-app alert to every admin when a customer opens a dispute (no email). */
async function alertDispute(d: Stripe.Dispute): Promise<void> {
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (!admins.length) return;
  const due = d.evidence_details?.due_by ? new Date(d.evidence_details.due_by * 1000).toISOString().slice(0, 10) : "see Stripe";
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `URGENT: card dispute opened (${(d.amount / 100).toFixed(2)} ${d.currency.toUpperCase()})`,
      body: `Reason: ${String(d.reason).replace(/_/g, " ")}. Evidence due ${due}. Dispute ${d.id} — respond in the Stripe dashboard.`,
      href: "/admin/billing",
    })),
  });
}

