class AlreadyRefundedError extends Error {}

function parseAmountCents(raw: FormDataEntryValue | null): number | null {
  const amount = Number(raw);
  if (!Number.isFinite(amount) || amount === 0) return null;
  if (Math.abs(amount) > 50000) return null; // sanity cap: $50k / action
  return Math.round(amount * 100);
}

/** Pull a Stripe checkout-session id (cs_...) out of a wallet-transaction note. */
function sessionIdFrom(description: string | undefined | null): string | null {
  const m = (description ?? "").match(/cs_[A-Za-z0-9_]+/);
  return m ? m[0] : null;
}

/**
 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
 * is configured, the money is returned to the original card via the recovered
 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
 * debits the wallet balance and records the ledger entry.
 *
 * Safety: the wallet is never driven below zero — for a wallet-only refund we
 * require sufficient balance; for a Stripe refund of already-spent funds we
 * decrement only what remains (the rest is a real-cash write-off) and note it.
