  // heading naming one invoice, pre-filled with that invoice's total — but the id
  // was never sent, so the action guessed its Stripe target as "most recent top-up,
  // any amount". Refunding a $24 March invoice therefore issued $24 against the
  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
  // to refund it all over again.
  const invoiceId = String(formData.get("invoiceId") ?? "").trim();

  if (!userId) return { error: "Missing customer." };
  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  // Resolve and validate the target invoice when one was supplied.
  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
  // How much of the invoice was already refunded WHEN WE READ IT. Two jobs: it is
  // the compare-and-swap anchor for the write below, and it is what makes the
  // Stripe idempotency key describe a STEP of the refund rather than an amount.
  let alreadyRefunded = 0;
  if (invoiceId) {
    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
    if (!invoice) return { error: "Invoice not found." };
    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
    alreadyRefunded = invoice.refundedCents ?? 0;
    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
    if (refundable === 0) {
      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
    }
    if (cents > refundable) {
      return {
        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
      };
    }
  }

  // --- Route the refund back to the ORIGINAL card for this charge ---
  let method: "stripe" | "wallet" = "wallet";
  let stripeRefundId: string | null = null;
  if (stripeConfigured()) {
