 *  - wallet top-ups (money IN, not a purchase — the service it later funds is its
 *    own invoice and is what earns the commission; accruing on both would double
 *    count). "Wallet top-up" is lib/stripe.ts; "Automatic wallet top-up" is the
 *    auto-recharge in worker/billing.ts (AUTO_RECHARGE_DESC).
 * Refunds/credits are excluded separately by the `amountCents <= 0` guard below.
 */
export const NON_COMMISSIONABLE_DESCRIPTIONS = new Set(["Wallet top-up", "Automatic wallet top-up"]);

export type CommissionableInvoice = Pick<
  Invoice,
  "id" | "userId" | "status" | "amountCents" | "taxCents" | "description" | "createdAt" | "dedicatedIpCents"
>;

/**
 * Is this invoice a qualifying charge a partner earns commission on? True for any
 * PAID invoice with a positive total that isn't a wallet top-up. This is the one
 * classifier every accrual path shares.
 */
export function isCommissionableInvoice(inv: CommissionableInvoice): boolean {
  if (inv.status !== "PAID") return false;
  if (inv.amountCents <= 0) return false; // refunds / zero-value docs
  if (NON_COMMISSIONABLE_DESCRIPTIONS.has(inv.description.trim())) return false;
  return true;
}

/**
 * The commission BASE for an invoice: net (pre-tax) charge, minus the dedicated-IP
 * portion of it — the owner's spec is explicit that a partner earns 0% commission
 * on a dedicated-IP add-on line, but 100% of the normal rate on every other line
 * in the same order/renewal (base plan, extra disk, backup tier, any other
 * add-on). Pure function — no DB — so it's directly unit-tested
 * (test/partner-discount.test.ts) against the boundary cases: an order with only
 * a dedicated IP (base -> 0), an order with no dedicated IP (unaffected), and a
 * mixed-addon order (only the IP slice excluded). Clamped so a corrupt/negative
 * `dedicatedIpCents` can never inflate the base past the net charge.
 */
export function commissionableBaseCents(netCents: number, dedicatedIpCents: number): number {
  const ip = Math.max(0, dedicatedIpCents || 0);
  return Math.max(0, netCents - ip);
}

