  reason?: string,
): Promise<CommissionReversal | null> {
  return applyCommissionReversal(
    invoiceId,
    ({ invoice, rows }) => {
      const refunded = invoiceLedgerRefundedCents(invoice);
      if (refunded <= 0) return null;
      const covered = rows.reduce((max, r) => {
        if (!r.reversalKey.startsWith("ledger:")) return max;
        const n = Number(r.reversalKey.slice("ledger:".length));
        return Number.isFinite(n) ? Math.max(max, n) : max;
      }, 0);
      if (refunded <= covered) return null;
      return { key: `ledger:${refunded}`, refundCents: refunded - covered };
    },
    reason,
  );
}

/**
 * Never-throwing wrapper for the refund hook sites. A commission-ledger hiccup
 * must never fail, or roll back, a customer's refund — the refund has already
 * committed by the time this runs. A failure is logged AND written to AuditLog
 * (`partner.commission_reversal_failed`) so it's visible to ops rather than lost.
 */
export async function reverseCommissionSafely(
  label: string,
  run: () => Promise<CommissionReversal | null>,
): Promise<CommissionReversal | null> {
  try {
    return await run();
  } catch (e) {
    console.error("[partner-commission] reversal failed:", label, e);
    await db.auditLog
      .create({
        data: {
          userId: null,
          action: "partner.commission_reversal_failed",
          category: "billing",
          detail: `${label}: ${(e as Error)?.message ?? String(e)}`.slice(0, 500),
        },
      })
      .catch(() => {});
    return null;
  }
}

