export function isOfferTerm(n: number): boolean {
  return (OFFER_TERM_MONTHS as readonly number[]).includes(n);
}

/** F derived from a percent off the regular term price. */
export function firstTermFromDiscount(renewalMonthlyCents: number, termMonths: number, discountPercent: number): number {
  const pct = Math.min(100, Math.max(0, Number(discountPercent) || 0));
  return Math.round(renewalMonthlyCents * termMonths * (1 - pct / 100));
}

export function termPromoPercentFor(firstTermCents: number, renewalMonthlyCents: number, termMonths: number): number {
  const regular = renewalMonthlyCents * termMonths;
  if (regular <= 0) return 0;
  const pct = (1 - firstTermCents / regular) * 100;
  return Math.min(100, Math.max(0, Math.round(pct * 100) / 100));
}

export function offerTotals(t: Pick<OfferTerms, "kind" | "extras" | "pricing">): OfferTotals {
  const months = t.pricing.termMonths;
  const ipMonthly = t.kind !== "DEDICATED" && t.extras.dedicatedIp ? Math.max(0, t.pricing.ipMonthlyCents) : 0;
  const ipTermCents = ipMonthly * months;
  const base = t.pricing.firstTermCents;
  const setup = t.pricing.setupFeeCents;
  return {
    termMonths: months,
    baseFirstTermCents: base,
    setupFeeCents: setup,
    ipTermCents,
    dueNowNetCents: base + setup + ipTermCents,
    renewalTermCents: t.pricing.renewalMonthlyCents * months + ipTermCents,
    renewalMonthlyAllInCents: t.pricing.renewalMonthlyCents + ipMonthly,
    termPromoPercent: termPromoPercentFor(base, t.pricing.renewalMonthlyCents, months),
  };
}

