import { approveIpOrder, IpOrderError, rejectIpOrder } from "./dedicated/ip-order";
import { isSshPublicKey, parseServerHostname } from "./dedicated/ops-core";

type R = { ok: true; message?: string } | { ok: false; error: string };
const err = (e: unknown): R => ({ ok: false, error: e instanceof IpOrderError || e instanceof Error ? e.message : "Failed" });

export async function adminApproveIpOrder(orderId: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const jobId = await approveIpOrder(orderId, admin.id);
    const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, select: { dedicatedServerId: true } });
    if (o) revalidatePath(`/admin/dedicated/servers/${o.dedicatedServerId}`);
    return { ok: true, message: `Approved. Worker job ${jobId} will place the order.` };
  } catch (e) {
    return err(e);
  }
}

export async function adminRejectIpOrder(orderId: string, reason: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    await rejectIpOrder(orderId, admin.id, String(reason ?? ""));
    const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, select: { dedicatedServerId: true } });
    if (o) revalidatePath(`/admin/dedicated/servers/${o.dedicatedServerId}`);
    return { ok: true, message: "Rejected and refunded to the customer's wallet." };
  } catch (e) {
    return err(e);
  }
}

