  walletApplied: number;
  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
  cardCents: number;
  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
  clampedForStripeMin: boolean;
  /**
   * True when the WHOLE amount due is under Stripe's floor, so no card leg exists
   * at all and `walletApplied` is the entire due (see walletSplit). Distinct from
   * `clampedForStripeMin`, which means the opposite thing — that a card leg does
   * exist and was raised to the floor. Surfaces must not conflate them: the deploy
   * wizard's `clampedForStripeMin` line says "we'll charge {cardCents} to your
   * card", which would be a flat lie here, where `cardCents` is 0.
   *
