/**
 * Dedicated-server pricing rules — PURE (no DB, no clock), so the money math is
 * unit-tested in isolation (test/dedicated-pricing.test.ts).
 *
 * Nxeon price = round( (cost x (1 + markup%) + fixed markup) x (1 + uplift%) ),
 * per the rounding mode, unless the item carries a hard price override.
 *
 * `upliftPercent` (Setting dedicated_price_uplift_percent, default 10) is a
 * price increase applied ON TOP of whatever markup is in force (owner decision
 * 2026-10-07: "increase markup by another 10%"). It is multiplicative and
 * separate from the markup so it survives any change to the markup itself, and
 * it reaches options too. A hard `overrideMonthlyCents` is an exact admin price
 * and is NOT uplifted (options chosen on top of it still are). The markup applies to
 * the configured options (RAM/storage/bandwidth upgrades) too, so a bigger
 * build never sells below cost. All amounts are integer cents in the
 * catalogue currency (USD for the subsidiary we sync by default).
 *
 * Where the knobs live:
 *   - global defaults: Settings (dedicated_markup_percent, dedicated_markup_fixed_cents,
 *     dedicated_rounding, dedicated_setup_policy, dedicated_setup_custom_cents)
 *   - per item: DedicatedCatalogItem.markupPercent / markupFixedCents /
 *     overrideMonthlyCents / setupPolicy / setupCustomCents (null = inherit)
 */

export const ROUNDING_MODES = ["none", "whole", "ninety-nine", "five"] as const;
export type RoundingMode = (typeof ROUNDING_MODES)[number];

export const SETUP_POLICIES = ["pass", "waived", "custom"] as const;
export type SetupPolicy = (typeof SETUP_POLICIES)[number];

export type PricingRules = {
  markupPercent: number;
  markupFixedCents: number;
  rounding: RoundingMode;
  setupPolicy: SetupPolicy;
  setupCustomCents: number;
  /** Extra % applied after the markup (see the header). 0 = none. */
  upliftPercent: number;
};

export type ItemPricingOverride = {
  markupPercent?: number | null;
  markupFixedCents?: number | null;
  overrideMonthlyCents?: number | null;
  setupPolicy?: string | null;
  setupCustomCents?: number | null;
};

export const DEFAULT_RULES: PricingRules = {
  markupPercent: 25,
  markupFixedCents: 0,
  rounding: "ninety-nine",
  setupPolicy: "pass",
  setupCustomCents: 0,
  upliftPercent: 10,
};

export function isRoundingMode(v: string): v is RoundingMode {
  return (ROUNDING_MODES as readonly string[]).includes(v);
}
export function isSetupPolicy(v: string): v is SetupPolicy {
  return (SETUP_POLICIES as readonly string[]).includes(v);
}

/** Build rules from raw setting strings; anything unparseable falls back to DEFAULT_RULES. */
export function rulesFromSettings(s: Record<string, string | undefined>): PricingRules {
  const n = (v: string | undefined, d: number) => {
    const x = Number(v);
    return v != null && v.trim() !== "" && Number.isFinite(x) ? x : d;
  };
  const rounding = s.dedicated_rounding ?? "";
  const policy = s.dedicated_setup_policy ?? "";
  return {
    markupPercent: clampPercent(n(s.dedicated_markup_percent, DEFAULT_RULES.markupPercent)),
    markupFixedCents: Math.round(n(s.dedicated_markup_fixed_cents, DEFAULT_RULES.markupFixedCents)),
    rounding: isRoundingMode(rounding) ? rounding : DEFAULT_RULES.rounding,
    setupPolicy: isSetupPolicy(policy) ? policy : DEFAULT_RULES.setupPolicy,
    setupCustomCents: Math.max(0, Math.round(n(s.dedicated_setup_custom_cents, DEFAULT_RULES.setupCustomCents))),
    upliftPercent: Math.min(200, Math.max(0, n(s.dedicated_price_uplift_percent, DEFAULT_RULES.upliftPercent))),
  };
}

/** A markup below -100% would produce a negative price; above 1000% is a typo. */
export function clampPercent(p: number): number {
  if (!Number.isFinite(p)) return DEFAULT_RULES.markupPercent;
  return Math.min(1000, Math.max(-100, p));
}

/** Apply a rounding mode. Every mode rounds UP (never below the computed price). */
export function roundPrice(cents: number, mode: RoundingMode): number {
  const c = Math.max(0, Math.round(cents));
  switch (mode) {
    case "none":
      return c;
    case "whole":
      return Math.ceil(c / 100) * 100;
    case "ninety-nine":
      // smallest X.99 >= c  (13375 -> 13399, 13399 -> 13399, 13400 -> 13499, 0 -> 99)
      return Math.ceil((c + 1) / 100) * 100 - 1;
    case "five":
      return Math.ceil(c / 500) * 500;
  }
}

/** Effective markup for one item (item override wins, else the global rule). */
export function effectiveMarkup(rules: PricingRules, o: ItemPricingOverride = {}): { percent: number; fixedCents: number } {
  return {
    percent: o.markupPercent != null ? clampPercent(o.markupPercent) : rules.markupPercent,
    fixedCents: o.markupFixedCents != null ? Math.round(o.markupFixedCents) : rules.markupFixedCents,
  };
}

/**
 * Nxeon monthly price for a cost (base plan + any chosen option costs).
 * `overrideMonthlyCents` is a hard price for the DEFAULT build; options chosen
 * on top of it are still marked up so an override can't silently give away
 * upgrades at cost.
 */
export function sellMonthlyCents(baseCostCents: number, rules: PricingRules, o: ItemPricingOverride = {}, optionCostCents = 0): number {
  const { percent, fixedCents } = effectiveMarkup(rules, o);
  const up = 1 + (rules.upliftPercent ?? 0) / 100;
  const markOpts = optionCostCents * (1 + percent / 100) * up;
  if (o.overrideMonthlyCents != null && o.overrideMonthlyCents >= 0) {
    return Math.round(o.overrideMonthlyCents) + Math.ceil(markOpts - 1e-9);
  }
  const raw = ((baseCostCents + optionCostCents) * (1 + percent / 100) + fixedCents) * up;
  return roundPrice(raw - 1e-9, rules.rounding);
}

