 * also only renders for VPS and game servers. The Terms also name hosting plans, but the
 * first-time test the server applies is "no paid Server rows yet", which cannot tell a
 * returning hosting buyer from a new one — so hosting, business email and domains show
 * nothing rather than risk promising a refund the Terms would not give.
 */
export function MoneyBackNote({ className = "" }: { className?: string }) {
  const { o, cat } = useOrder();
  const mb = cat.moneyBack;
  if (!mb) return null;
  if (o.service !== "vps" && o.service !== "game") return null;
  return (
