function toCheck(v: CreatorCodeVerdict): CreatorCodeCheck {
  if (v.kind === "refused") return { kind: "refused", code: v.code, message: v.message };
  return v;
}

export async function checkCreatorCode(rawCode: string): Promise<CreatorCodeCheck> {
  const user = await requireUser();
  const code = String(rawCode ?? "").slice(0, 64);
