  const rl = checkRateLimit(`creator-code-check:${user.id}`, { max: 40, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) return { kind: "refused", code: code.toUpperCase(), message: `Too many code checks. Try again in ${rl.retryAfterSec}s.` };
