/**
 * Nxeon setup fee. "pass" passes through what the setup costs us right now —
 * the promotional setup when a live upstream promotion lowers it, else the
 * list setup fee. "waived" = 0. "custom" = a fixed admin-set fee.
 */
export function sellSetupCents(
  costSetupCents: number,
  rules: PricingRules,
  o: ItemPricingOverride = {},
  promoSetupCents: number | null = null,
): number {
  const policy = o.setupPolicy && isSetupPolicy(o.setupPolicy) ? o.setupPolicy : rules.setupPolicy;
  if (policy === "waived") return 0;
  if (policy === "custom") return Math.max(0, Math.round(o.setupCustomCents ?? rules.setupCustomCents));
  return Math.max(0, Math.round(promoSetupCents ?? costSetupCents));
}

